  ('crs_sustainable', 'p_leo', 'Sustainable Living', 'A practical guide', 'Small, realistic changes for a lighter footprint at home — food, energy, stuff and community.', '/media/learn-sustainable.webp', 'guide', 'Sustainability', 120000, null, null),
  ('crs_digital', 'p_ana', 'Digital Skills', 'Build your future', 'The practical tools of modern remote work: writing clearly, organising your work and collaborating online.', '/media/learn-digital.webp', 'course', 'Careers', 68000, null, null),
  ('crs_wellness', 'p_josie', 'Health & Wellness', 'Mind • Body', 'Gentle routines for energy, focus and rest — built around real, busy lives.', '/media/learn-health.webp', 'course', 'Wellness', 74000, null, null),
  ('crs_writing', 'p_maya', 'Creative Writing', 'Live workshop', 'A friendly live workshop: short prompts, shared drafts and kind feedback.', '/media/learn-writing.webp', 'live', 'Creativity', 31000, now() + interval '172800000 milliseconds', null),
  ('crs_garden', 'p_leo', 'Grow Your Own', 'Balcony gardening', 'Herbs, salad and tomatoes in small spaces — containers, soil, light and watering.', '/media/learn-garden.webp', 'guide', 'Sustainability', 42000, null, null),
  ('crs_shop', 'p_maya', 'Start a Small Shop', 'From idea to first sale', 'Open your MarketPlace shop: products, photos, pricing and getting paid with Stripe.', '/media/learn-shop.webp', 'course', 'Business', 27000, null, 2900)
