insert into public.lesson_bodies (lesson_id, course_id, body) values
  ('sus_l1', 'crs_sustainable', 'Pick the change that is easiest for you, not the one that looks best. Consistency beats intensity: a habit you keep for a year does more than a dramatic week.'),
  ('sus_l2', 'crs_sustainable', 'Plan three meals ahead, shop with a list and keep a "use first" shelf in the fridge. Freeze bread and herbs before they turn. Compost what is left.'),
  ('sus_l3', 'crs_sustainable', 'Draught-proof doors and windows, lower the heating by one degree and wash at 30°C. Switch to a renewable tariff if one is available where you live.'),
  ('sus_l4', 'crs_sustainable', 'Borrow, repair and buy second-hand first. When you buy new, choose things that can be mended and will be loved for a long time.'),
  ('dig_l1', 'crs_digital', 'Lead with the point. Use short paragraphs and one idea per message. End with the decision or action you need.'),
  ('dig_l2', 'crs_digital', 'Keep one list. Sort by what moves your goals, not by what is loudest. Block focus time before meetings fill it.'),
  ('dig_l3', 'crs_digital', 'Share context in writing, record short videos for walkthroughs and agree on response times with your team.'),
  ('dig_l4', 'crs_digital', 'Show three pieces of work with the problem, what you did and the result. Keep it short and link to it everywhere.'),
  ('wel_l1', 'crs_wellness', 'Keep the first ten minutes screen-free. Water, light and a short walk set the tone for the day.'),
  ('wel_l2', 'crs_wellness', 'The best exercise is the one you will do. Two short walks count. So does dancing in the kitchen.'),
  ('wel_l3', 'crs_wellness', 'Protect a wind-down hour. Dim lights, write tomorrow’s list and put the phone in another room.'),
  ('wri_l1', 'crs_writing', 'Write for five minutes without stopping. Do not edit. Circle one sentence you like.'),
  ('wri_l2', 'crs_writing', 'Read your circled sentence aloud. What makes it sound like you? Write a paragraph that keeps that sound.'),
  ('gar_l1', 'crs_garden', 'Most edibles need six hours of sun. Use pots with drainage holes and at least 20 cm of depth.'),
  ('gar_l2', 'crs_garden', 'Use peat-free compost and feed every two weeks in summer.'),
  ('gar_l3', 'crs_garden', 'Start with mint, basil, lettuce and cherry tomatoes. They forgive mistakes.'),
  ('shp_l1', 'crs_shop', 'Start small. Three great products tell a clearer story than thirty.'),
  ('shp_l2', 'crs_shop', 'Use daylight, a plain background and show the object in use.'),
  ('shp_l3', 'crs_shop', 'Materials + time + overheads, then check what similar makers charge. Do not undercharge.'),
  ('shp_l4', 'crs_shop', 'Create a Stripe Payment Link for each product and paste it into your listing. Buyers pay you directly.')
